begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values ('33333333-3333-4333-8333-333333333333','import@daywise.test');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
insert into profiles(id,"displayName") values ('history','History');
select daywise_income('history','2024-02',100001,'default');
select daywise_commitment('{"id":"rent","profileId":"history","yearMonth":"2024-02","name":"Rent","category":"Rent","amountMinor":20003,"origin":"recurring","paid":true,"notes":""}','future');
select daywise_ensure_month('history','2025-02');
select daywise_ensure_month('history','2026-04');
select daywise_ensure_month('history','2026-10');
select is((select count(*) from monthly_plans where "profileId"='history'),4::bigint,'All month lengths materialised');
select is((select count(*) from monthly_commitments where "profileId"='history'),4::bigint,'One source snapshot per month');
select daywise_ensure_month('history','2026-10');
select is((select count(*) from monthly_commitments where "profileId"='history'),4::bigint,'Month materialisation idempotent');
select daywise_income('history','2025-02',0,'month');
select daywise_income('history','2026-04',100003,'default');
select is((select "monthlyIncomeMinor"::bigint from monthly_plans where "profileId"='history' and "yearMonth"='2024-02'),100001::bigint,'Historical income preserved');
select is((select "monthlyIncomeMinor"::bigint from monthly_plans where "profileId"='history' and "yearMonth"='2025-02'),0::bigint,'Zero-income override preserved');
select is((select "monthlyIncomeMinor"::bigint from monthly_plans where "profileId"='history' and "yearMonth"='2026-10'),100003::bigint,'New default propagated');
select daywise_paid('history','rent');
select is((select "amountMinor"::bigint from monthly_commitments where id='rent'),20003::bigint,'Payment status never changes reserved amount');
select daywise_commitment('{"id":"later-rent","profileId":"history","yearMonth":"2026-04","sourceId":null,"name":"One time","category":"Other","amountMinor":7,"origin":"one-time","paid":false,"notes":""}','month');
select is((select count(*) from monthly_commitments where "profileId"='history' and "yearMonth"='2026-10'),1::bigint,'One-time commitments do not recur');
-- Recurring propagation preserves historical snapshots and future month overrides.
select daywise_paid('history',(select id from monthly_commitments where "profileId"='history' and "yearMonth"='2026-10'));
select daywise_commitment((select to_jsonb(c)||'{"amountMinor":23001}'::jsonb from monthly_commitments c where "profileId"='history' and "yearMonth"='2026-04' and origin='recurring'),'future');
select is((select "amountMinor"::bigint from monthly_commitments where id='rent'),20003::bigint,'Recurring revision preserves historical amount');
select is((select "amountMinor"::bigint from monthly_commitments where "profileId"='history' and "yearMonth"='2026-10'),23001::bigint,'Recurring revision propagates to materialised future month');
select ok((select paid from monthly_commitments where "profileId"='history' and "yearMonth"='2026-10'),'Propagation preserves paid status');
select daywise_commitment((select to_jsonb(c)||'{"amountMinor":777}'::jsonb from monthly_commitments c where "profileId"='history' and "yearMonth"='2026-10'),'month');
select daywise_commitment((select to_jsonb(c)||'{"amountMinor":24001}'::jsonb from monthly_commitments c where "profileId"='history' and "yearMonth"='2026-04' and origin='recurring'),'future');
select is((select "amountMinor"::bigint from monthly_commitments where "profileId"='history' and "yearMonth"='2026-10'),777::bigint,'Future month override survives propagation');
select daywise_remove('history',(select id from monthly_commitments where "profileId"='history' and "yearMonth"='2026-10'),false);
select daywise_commitment((select to_jsonb(c)||'{"amountMinor":25001}'::jsonb from monthly_commitments c where "profileId"='history' and "yearMonth"='2026-04' and origin='recurring'),'future');
select ok((select excluded from monthly_commitments where "profileId"='history' and "yearMonth"='2026-10'),'Excluded month stays excluded after revision');
select daywise_commitment((select to_jsonb(c) from monthly_commitments c where "profileId"='history' and "yearMonth"='2026-04' and origin='recurring'),'future','{"active":false}');
select is((select count(*) from monthly_commitments where "profileId"='history' and "yearMonth">='2026-04' and origin='recurring'),0::bigint,'Pause removes current/future snapshots atomically');
select is((select count(*) from monthly_commitments where "profileId"='history' and "yearMonth"<'2026-04'),2::bigint,'Pause preserves historical snapshots');
select daywise_commitment('{"id":"converted","profileId":"history","yearMonth":"2026-04","name":"Converted","category":"Other","amountMinor":103,"origin":"one-time","paid":false,"notes":""}','future');
select is((select count(*) from monthly_commitments where "profileId"='history' and "yearMonth"='2026-10'),1::bigint,'One-time conversion creates future recurring snapshot');
-- Actual export shape is accepted by import, including optional nulls.
create temp table backup as select daywise_export('history') as b;
grant select,update on backup to authenticated;
update backup set b=jsonb_set(b,'{profile,id}','"imported"');
update backup set b=jsonb_set(b,'{profile,displayName}','"Imported history"');
-- Remap every row/source using deterministic UUID namespaces (client uses SHA-256).
update backup set b=b || (select jsonb_object_agg(k,coalesce((select jsonb_agg(v || jsonb_build_object('id','copy-'||(v->>'id'),'profileId','imported') || case when v->>'sourceId' is not null then jsonb_build_object('sourceId','copy-'||(v->>'sourceId')) else '{}'::jsonb end) from jsonb_array_elements(b->k) v),'[]'::jsonb)) from unnest(array['incomes','recurring','plans','commitments','expenses','categories']) k);
select lives_ok($q$select daywise_import(b,'local-source',repeat('b',64),daywise_manifest(b),'33333333-3333-4333-8333-333333333333') from backup$q$,'Import succeeds transactionally');
select is(daywise_manifest(daywise_export('history')),daywise_manifest(daywise_export('imported')),'Exact counts, historical income, fixed and expense paise match');
select is((select daywise_import(b,'local-source',repeat('b',64),daywise_manifest(b),'33333333-3333-4333-8333-333333333333')->>'repeated' from backup),'true','Interrupted response retry returns original receipt');
select is((select count(*) from profiles),2::bigint,'Retry creates no duplicate workspace');
select throws_ok($q$select daywise_import(b,'local-source',repeat('c',64),daywise_manifest(b),'33333333-3333-4333-8333-333333333333') from backup$q$,'23505',null,'Changed source cannot silently merge');
update backup set b=jsonb_set(b,'{profile,id}','"broken"');
select throws_ok($q$select daywise_import(b,'broken-source',repeat('d',64),daywise_manifest(b),'33333333-3333-4333-8333-333333333333') from backup$q$,'42501',null,'Mixed parent import fails');
select is((select count(*) from profiles where id='broken'),0::bigint,'Failed import rolls back entire profile');
select is((select count(*) from local_migrations where source_profile='broken-source'),0::bigint,'Failed import leaves no receipt');
select throws_ok($q$select daywise_import(b,'bad-count',repeat('e',64),'{}','33333333-3333-4333-8333-333333333333') from backup$q$,'P0001',null,'Incorrect manifest rejected');
delete from profiles where id='imported';
select ok((select profile_id is null from local_migrations where source_profile='local-source'),'Receipt retains safe nullable reference after workspace deletion');
select throws_ok($q$select daywise_import(b,'local-source',repeat('b',64),daywise_manifest(b),'33333333-3333-4333-8333-333333333333') from backup$q$,'42501',null,'Delayed retry never recreates deleted workspace');
select * from finish();
rollback;
